package com.fixmer.genesis.technology.workspace;
import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;
import static com.fixmer.genesis.technology.workspace.WorkspaceWire112.*;
/** Lifetime file lock, serialized mutations, checksummed atomic snapshots. User paths are logical keys only. */
public final class WorkspaceStore112 implements AutoCloseable {
 private static final int MAGIC=0x47573112,MAX_STATE=32*1024*1024,MAX_PROJECTS=32,MAX_FILES=96,MAX_MEMBERS=32,MAX_RECEIPTS=128;
 private static final Set<Path> OPEN=java.util.concurrent.ConcurrentHashMap.newKeySet();
 public enum Role{OWNER,MANAGER,EDITOR,VIEWER}
 private record Document(UUID id,long revision,String text){}
 private static final class Project{UUID id,owner;String title;long revision;final TreeMap<UUID,Role> members=new TreeMap<>();final TreeMap<String,Document> files=new TreeMap<>();final ArrayDeque<String> history=new ArrayDeque<>();}
 private record Receipt(UUID actor,String hash,UUID project){}
 private static final class State{UUID id;final TreeMap<UUID,Project> projects=new TreeMap<>();final LinkedHashMap<UUID,Receipt> receipts=new LinkedHashMap<>();}
 private final Path directory,snapshot;private final FileChannel channel;private final FileLock lock;private State state;private boolean closed;
 public WorkspaceStore112(Path folder)throws IOException{
  Path requested=folder.toAbsolutePath().normalize();safe(requested);Files.createDirectories(requested);safe(requested);
  directory=requested.toRealPath();snapshot=directory.resolve("workspace112.bin");
  Path guard=directory.resolve("workspace112.lock");safe(guard);
  // On POSIX, closing a second descriptor can release this JVM's first lock.
  if(!OPEN.add(directory))throw new IOException("LOCKED");
  try{channel=FileChannel.open(guard,StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);}
  catch(IOException|RuntimeException bad){OPEN.remove(directory);throw bad;}
  FileLock acquired=null;
  try{acquired=channel.tryLock();if(acquired==null)throw new IOException("LOCKED");lock=acquired;
   if(Files.exists(snapshot,LinkOption.NOFOLLOW_LINKS)){
    safe(snapshot);
    if(!Files.isRegularFile(snapshot,LinkOption.NOFOLLOW_LINKS)||Files.size(snapshot)>MAX_STATE)throw new IOException("CORRUPT");
    try(var in=Files.newInputStream(snapshot,LinkOption.NOFOLLOW_LINKS)){state=read(in.readNBytes(MAX_STATE+1));}
   }else{state=new State();state.id=UUID.randomUUID();persist(state);}
   try(var entries=Files.newDirectoryStream(directory,".workspace112-*.tmp")){for(Path p:entries)if(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))Files.deleteIfExists(p);}
  }catch(Exception bad){try{if(acquired!=null)acquired.release();}catch(IOException cleanup){bad.addSuppressed(cleanup);}
   try{channel.close();}catch(IOException cleanup){bad.addSuppressed(cleanup);}finally{OPEN.remove(directory);}
   if(bad instanceof IOException io)throw io;throw new IOException("LOCKED",bad);}
 }
 private static void safe(Path p)throws IOException{for(Path a=p;a!=null;a=a.getParent())if(Files.exists(a,LinkOption.NOFOLLOW_LINKS)){var attr=Files.readAttributes(a,java.nio.file.attribute.BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(attr.isSymbolicLink()||attr.isOther()||!a.toRealPath().equals(a.toRealPath(LinkOption.NOFOLLOW_LINKS)))throw new IOException("LINK");}}
 private static UUID uuid(String value)throws IOException{try{UUID id=UUID.fromString(value);if(!id.toString().equals(value))throw new IllegalArgumentException();return id;}catch(RuntimeException bad){throw new IOException("INVALID");}}
 public static String path(String value)throws IOException{if(value.isEmpty()||value.length()>120||!value.matches("[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)*"))throw new IOException("INVALID_PATH");for(String p:value.split("/"))if(p.equals(".")||p.equals("..")||p.startsWith(".")||p.endsWith(".")||p.matches("(?i)(CON|PRN|AUX|NUL|COM[0-9]|LPT[0-9])(?:\\..*)?"))throw new IOException("INVALID_PATH");return value;}
 private static String title(String text)throws IOException{try{unicode(text);}catch(RuntimeException bad){throw new IOException("INVALID");}if(text.isBlank()||text.length()>64||text.chars().anyMatch(Character::isISOControl))throw new IOException("INVALID");return text;}
 private static String text(String s)throws IOException{try{unicode(s);}catch(RuntimeException bad){throw new IOException("INVALID");}if(s.indexOf(0)>=0||s.getBytes(StandardCharsets.UTF_8).length>MAX_TEXT)throw new IOException("LIMIT");return s.replace("\r\n","\n").replace('\r','\n');}
 private static Role role(Project p,UUID actor)throws IOException{Role r=p.members.get(actor);if(r==null)throw new IOException("DENIED");return r;}
 private static void edit(Role r)throws IOException{if(r==Role.VIEWER)throw new IOException("DENIED");}
 private static void manage(Role r)throws IOException{if(r!=Role.OWNER&&r!=Role.MANAGER)throw new IOException("DENIED");}
 private static void exact(Project p,long revision)throws IOException{if(p.revision!=revision)throw new IOException("CONFLICT");}
 private static boolean collision(Project p,String name){return p.files.keySet().stream().anyMatch(s->s.equalsIgnoreCase(name));}
 private static Document document(Project p,Request q)throws IOException{Document d=p.files.get(path(q.path()));if(d==null)throw new IOException("NOT_FOUND");if(!q.file().isEmpty()&&!d.id().toString().equals(q.file()))throw new IOException("CONFLICT");return d;}
 private static byte[] hash(byte[] b){try{return MessageDigest.getInstance("SHA-256").digest(b);}catch(NoSuchAlgorithmException bad){throw new AssertionError(bad);}}
 private static String hash(Request q)throws IOException{return HexFormat.of().formatHex(hash(encode(q)));}
 public record Export122(UUID project,UUID owner,String title,long revision,Map<UUID,Role> members,Map<String,String> files){public Export122{members=Map.copyOf(members);files=Map.copyOf(files);}}
 public synchronized Export122 freeze122(UUID actor,UUID project)throws IOException{if(closed)throw new IOException("CLOSED");Project p=state.projects.get(project);if(p==null||!p.owner.equals(actor))throw new IOException("DENIED");if(p.files.size()>64)throw new IOException("LIMIT");long total=0;var files=new TreeMap<String,String>();for(var e:p.files.entrySet()){com.fixmer.genesis.technology.workspace.collaboration121.WorkspacePolicy121.path(e.getKey());String text=e.getValue().text();int n=text.codePointCount(0,text.length());total+=n;if(n>8192||total>100000)throw new IOException("LIMIT");files.put(e.getKey(),text);}Path seals=directory.resolve("migrated122");safe(seals);Files.createDirectories(seals);Path marker=seals.resolve(project.toString());safe(marker);if(!Files.exists(marker))com.fixmer.genesis.technology.server.firstlaunch.FirstLaunchFiles.write(marker,(project+"\n"+p.revision+"\n").getBytes(StandardCharsets.US_ASCII),false);return new Export122(project,p.owner,p.title,p.revision,p.members,files);}
 public synchronized Map<String,String> execute(UUID actor,boolean mayCreate,Request q)throws IOException{
  if(closed)throw new IOException("CLOSED");Objects.requireNonNull(actor);
  if(q.operation().equals("LIST")){var d=base();var rows=new StringBuilder();for(Project p:state.projects.values())if(p.members.containsKey(actor))rows.append(p.id).append('|').append(p.members.get(actor)).append('|').append(p.title).append('\n');d.put("projects",rows.toString());d.put("canCreate",Boolean.toString(mayCreate));return d;}
  Project current=q.operation().equals("CREATE")?null:state.projects.get(uuid(q.project()));if(current==null&&!q.operation().equals("CREATE"))throw new IOException("DENIED");if(current!=null)role(current,actor);
  Receipt receipt=state.receipts.get(q.request());if(receipt!=null){if(!receipt.actor.equals(actor)||!receipt.hash.equals(hash(q)))throw new IOException("REQUEST_REUSED");Project p=state.projects.get(receipt.project);if(p==null)throw new IOException("DENIED");role(p,actor);var d=view(p,actor);d.put("result","ALREADY_APPLIED");return d;}
  if(current!=null&&!Set.of("VIEW","READ","LIST").contains(q.operation())&&Files.exists(directory.resolve("migrated122").resolve(current.id.toString()),LinkOption.NOFOLLOW_LINKS))throw new IOException("MIGRATED");
  if(q.operation().equals("VIEW"))return view(current,actor);if(q.operation().equals("READ"))return content(current,document(current,q),q.path(),actor);
  if(q.operation().equals("CREATE")&&state.projects.containsKey(q.request())){Project old=state.projects.get(q.request());if(!old.owner.equals(actor)||!old.title.equals(q.text()))throw new IOException("REQUEST_REUSED");var d=view(old,actor);d.put("result","ALREADY_APPLIED");return d;}
  State next=read(serialize(state));Project p=current==null?null:next.projects.get(current.id);Role access=p==null?null:role(p,actor);
  if(q.operation().equals("CREATE")){if(!mayCreate)throw new IOException("DENIED");if(next.projects.size()>=MAX_PROJECTS)throw new IOException("LIMIT");p=new Project();p.id=q.request();p.owner=actor;p.title=title(q.text());p.revision=1;p.members.put(actor,Role.OWNER);next.projects.put(p.id,p);}
  else{if(p.revision==Long.MAX_VALUE)throw new IOException("LIMIT");switch(q.operation()){
   case "SAVE"->{edit(access);Document d=document(p,q);if(d.revision()!=q.revision())throw new IOException("CONFLICT");p.files.put(q.path(),new Document(d.id(),p.revision+1,text(q.text())));}
   case "NEW"->{edit(access);exact(p,q.projectRevision());String name=path(q.path());if(p.files.size()>=MAX_FILES)throw new IOException("LIMIT");if(collision(p,name))throw new IOException("EXISTS");p.files.put(name,new Document(UUID.randomUUID(),p.revision+1,text(q.text())));}
   case "RENAME","DELETE"->{manage(access);exact(p,q.projectRevision());Document d=document(p,q);if(d.revision()!=q.revision())throw new IOException("CONFLICT");if(q.operation().equals("RENAME")){String name=path(q.other());if(collision(p,name))throw new IOException("EXISTS");p.files.put(name,new Document(d.id(),p.revision+1,d.text()));}p.files.remove(q.path());}
   case "MEMBER"->{if(access!=Role.OWNER)throw new IOException("DENIED");exact(p,q.projectRevision());UUID target=uuid(q.target());if(target.equals(p.owner))throw new IOException("DENIED");if(q.role().equals("NONE"))p.members.remove(target);else{Role desired=Role.valueOf(q.role());if(desired==Role.OWNER)throw new IOException("DENIED");if(!p.members.containsKey(target)&&p.members.size()>=MAX_MEMBERS)throw new IOException("LIMIT");p.members.put(target,desired);}}
   default->throw new IOException("INVALID");}p.revision++;}
  if(size(p)>1024*1024)throw new IOException("LIMIT");p.history.addLast(p.revision+"|"+actor+"|"+q.operation()+"|"+(q.operation().equals("MEMBER")?q.target():q.path()));while(p.history.size()>64)p.history.removeFirst();
  next.receipts.put(q.request(),new Receipt(actor,hash(q),p.id));while(next.receipts.size()>MAX_RECEIPTS)next.receipts.remove(next.receipts.keySet().iterator().next());
  var answer=q.operation().equals("SAVE")||q.operation().equals("NEW")?content(p,p.files.get(q.path()),q.path(),actor):view(p,actor);answer.put("result","CHANGED");encode(view(p,actor));encode(answer);persist(next);state=next;return answer;
 }
 private static long size(Project p){long n=0;for(Document d:p.files.values())n+=d.text().getBytes(StandardCharsets.UTF_8).length;return n;}
 private TreeMap<String,String> base(){var d=new TreeMap<String,String>();d.put("result","STATE");d.put("store",state.id.toString());return d;}
 private TreeMap<String,String> view(Project p,UUID actor)throws IOException{var d=base();d.put("project",p.id.toString());d.put("title",p.title);d.put("role",role(p,actor).name());d.put("projectRevision",Long.toString(p.revision));var files=new StringBuilder();p.files.forEach((name,f)->files.append(f.id()).append('|').append(f.revision()).append('|').append(name).append('\n'));var members=new StringBuilder();p.members.forEach((id,r)->members.append(id).append('|').append(r).append('\n'));d.put("files",files.toString());d.put("members",members.toString());d.put("history",String.join("\n",p.history.stream().skip(Math.max(0,p.history.size()-12)).toList()));return d;}
 private TreeMap<String,String> content(Project p,Document f,String path,UUID actor)throws IOException{var d=base();d.put("project",p.id.toString());d.put("title",p.title);d.put("role",role(p,actor).name());d.put("projectRevision",Long.toString(p.revision));d.put("file",f.id().toString());d.put("path",path);d.put("revision",Long.toString(f.revision()));d.put("text",f.text());return d;}
 private static byte[] serialize(State s)throws IOException{var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){out.writeInt(MAGIC);out.writeUTF(s.id.toString());out.writeInt(s.projects.size());for(Project p:s.projects.values()){out.writeUTF(p.id.toString());out.writeUTF(p.owner.toString());out.writeUTF(p.title);out.writeLong(p.revision);out.writeInt(p.members.size());for(var e:p.members.entrySet()){out.writeUTF(e.getKey().toString());out.writeUTF(e.getValue().name());}out.writeInt(p.files.size());for(var e:p.files.entrySet()){out.writeUTF(e.getKey());out.writeUTF(e.getValue().id().toString());out.writeLong(e.getValue().revision());out.writeUTF(e.getValue().text());}out.writeInt(p.history.size());for(String e:p.history)out.writeUTF(e);}out.writeInt(s.receipts.size());for(var e:s.receipts.entrySet()){out.writeUTF(e.getKey().toString());out.writeUTF(e.getValue().actor.toString());out.writeUTF(e.getValue().hash);out.writeUTF(e.getValue().project.toString());}}if(bytes.size()+32>MAX_STATE)throw new IOException("LIMIT");byte[] body=bytes.toByteArray();bytes.write(hash(body));return bytes.toByteArray();}
 private static int count(DataInputStream in,int max)throws IOException{int n=in.readInt();if(n<0||n>max)throw new IOException("CORRUPT");return n;}
 private static State read(byte[] bytes)throws IOException{
  if(bytes.length<36||bytes.length>MAX_STATE)throw new IOException("CORRUPT");byte[] body=Arrays.copyOf(bytes,bytes.length-32);if(!MessageDigest.isEqual(hash(body),Arrays.copyOfRange(bytes,bytes.length-32,bytes.length)))throw new IOException("CORRUPT");var s=new State();
  try(var in=new DataInputStream(new ByteArrayInputStream(body))){if(in.readInt()!=MAGIC)throw new IOException("CORRUPT");s.id=uuid(in.readUTF());int projects=count(in,MAX_PROJECTS);for(int i=0;i<projects;i++){var p=new Project();p.id=uuid(in.readUTF());p.owner=uuid(in.readUTF());p.title=title(in.readUTF());p.revision=in.readLong();if(p.revision<1)throw new IOException("CORRUPT");int members=count(in,MAX_MEMBERS);for(int j=0;j<members;j++)if(p.members.put(uuid(in.readUTF()),Role.valueOf(in.readUTF()))!=null)throw new IOException("CORRUPT");if(p.members.get(p.owner)!=Role.OWNER||Collections.frequency(new ArrayList<>(p.members.values()),Role.OWNER)!=1)throw new IOException("CORRUPT");int files=count(in,MAX_FILES);Set<UUID> ids=new HashSet<>();for(int j=0;j<files;j++){String name=path(in.readUTF());UUID id=uuid(in.readUTF());long r=in.readLong();String t=text(in.readUTF());if(r<1||r>p.revision||!ids.add(id)||collision(p,name))throw new IOException("CORRUPT");p.files.put(name,new Document(id,r,t));}if(size(p)>1024*1024)throw new IOException("CORRUPT");int events=count(in,64);for(int j=0;j<events;j++)p.history.addLast(in.readUTF());if(s.projects.put(p.id,p)!=null)throw new IOException("CORRUPT");}int receipts=count(in,MAX_RECEIPTS);for(int i=0;i<receipts;i++){UUID id=uuid(in.readUTF()),actor=uuid(in.readUTF());String h=in.readUTF();UUID project=uuid(in.readUTF());if(!h.matches("[a-f0-9]{64}")||!s.projects.containsKey(project)||s.receipts.put(id,new Receipt(actor,h,project))!=null)throw new IOException("CORRUPT");}if(in.read()!=-1)throw new IOException("CORRUPT");return s;}catch(RuntimeException bad){throw new IOException("CORRUPT",bad);}
 }
 private void persist(State value)throws IOException{byte[] bytes=serialize(value);safe(directory);safe(snapshot);Path tmp=Files.createTempFile(directory,".workspace112-",".tmp");try{try(var out=FileChannel.open(tmp,StandardOpenOption.WRITE)){ByteBuffer b=ByteBuffer.wrap(bytes);while(b.hasRemaining())out.write(b);out.force(true);}Files.move(tmp,snapshot,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(tmp);}}
 @Override public synchronized void close()throws IOException{if(closed)return;closed=true;try{lock.release();}finally{try{channel.close();}finally{OPEN.remove(directory);}}}
}
